<?php include '../config.php'; if(!isAdmin()){header('Location: ../index.php');exit;} ?><?php if(isset($_POST['add'])){$conn->query("INSERT INTO products(name,description,price,stock_quantity,image_url,category_id) VALUES('{$conn->real_escape_string($_POST['name'])}','{$conn->real_escape_string($_POST['description'])}',{$_POST['price']},{$_POST['stock_quantity']},'{$_POST['image_url']}',{$_POST['category_id']})");} if(isset($_GET['delete']))$conn->query('DELETE FROM products WHERE product_id='.(int)$_GET['delete']); $p=$conn->query('SELECT * FROM products');$c=$conn->query('SELECT * FROM categories');?><!DOCTYPE html><html><head><link rel="stylesheet" href="../css/style.css"></head><body><div class="admin-layout"><?php include 'admin_nav.php'; ?><main class="admin-content"><h1>Products</h1><form class="form" method="POST"><input name="name" placeholder="Name"><textarea name="description"></textarea><input name="price" placeholder="Price"><input name="stock_quantity" placeholder="Stock"><input name="image_url" placeholder="Image URL"><select name="category_id"><?php while($x=$c->fetch_assoc()):?><option value="<?=$x['category_id']?>"><?=$x['name']?></option><?php endwhile;?></select><button name="add">Add</button></form><div class="table-box"><table><?php while($x=$p->fetch_assoc()):?><tr><td><?=$x['product_id']?></td><td><?=$x['name']?></td><td><?=$x['price']?></td><td><a class="btn" href="?delete=<?=$x['product_id']?>">Delete</a></td></tr><?php endwhile;?></table></div></main></div></body></html>